```javascript
// 1. Tab switching
document.querySelectorAll('.tab-btn').forEach(function(btn) {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.tab-btn').forEach(function(b) { b.classList.remove('active'); });
    document.querySelectorAll('.tab-content').forEach(function(c) { c.classList.remove('active'); });
    btn.classList.add('active');
    var tabId = btn.getAttribute('data-tab');
    document.getElementById(tabId).classList.add('active');
  });
});

// 2. Card selection - MUST use closest('.dc-section')
function selectCard(card) {
  var section = card.closest('.dc-section');
  if (section) {
    section.querySelectorAll('.dc-card').forEach(function(c) {
      c.classList.remove('selected');
    });
  }
  card.classList.add('selected');

  var varName = card.getAttribute('data-var');
  var varValue = card.getAttribute('data-val');
  if (varName && varValue && varName !== 'visual-only') {
    updateRootVar('--' + varName, varValue);
    // Sync with control panel dropdown
    var ctrl = document.getElementById('ctrl-' + varName);
    if (ctrl) {
      for (var i = 0; i < ctrl.options.length; i++) {
        if (ctrl.options[i].value === varValue) {
          ctrl.value = varValue;
          break;
        }
      }
    }
  }
}

// 3. Update CSS variable
function updateRootVar(name, value) {
  document.documentElement.style.setProperty(name, value);
}

// 4. Reset theme
function resetTheme() {
  var defaults = {
    '--heading-font': "'Playfair Display', serif",
    '--body-font': "'Inter', sans-serif",
    '--mono-font': "'DM Mono', monospace",
    '--accent-font': "'Inter', sans-serif",
    '--accent-gold': '#C9A96E',
    '--bg-body': '#0A0A0A',
    '--bg-card': '#141312',
    '--text-primary': '#F5F5F5',
    '--text-secondary': '#888888',
    '--color-green': '#2ECC71',
    '--color-red': '#E74C3C',
    '--color-orange': '#F39C12',
    '--border-radius': '6px',
    '--btn-radius': '6px',
    '--input-radius': '6px'
  };
  for (var k in defaults) {
    document.documentElement.style.setProperty(k, defaults[k]);
  }
  // Reset selected cards to first in each section
  document.querySelectorAll('.dc-section').forEach(function(s) {
    s.querySelectorAll('.dc-card').forEach(function(c, i) {
      if (i === 0) c.classList.add('selected');
      else c.classList.remove('selected');
    });
  });
  // Reset dropdowns
  document.querySelectorAll('.ctrl-group select').forEach(function(sel) {
    sel.selectedIndex = 0;
  });
}

// 5. Toggle control panel
function toggleCtrlPanel() {
  document.querySelector('.ctrl-panel').classList.toggle('collapsed');
}

// 6. Save theme as manifest
function saveTheme() {
  var manifest = { generatedAt: new Date().toISOString(), cssVariables: {}, selections: {} };
  var style = document.documentElement.style;
  for (var i = 0; i < style.length; i++) {
    var prop = style[i];
    if (prop.startsWith('--')) {
      manifest.cssVariables[prop] = style.getPropertyValue(prop).trim();
    }
  }
  document.querySelectorAll('.dc-card.selected').forEach(function(card) {
    var section = card.closest('.dc-section');
    var title = section ? section.querySelector('.dc-section-title').textContent : 'unknown';
    var label = card.querySelector('.dc-label span:first-child').textContent;
    manifest.selections[title] = label;
  });
  var blob = new Blob([JSON.stringify(manifest, null, 2)], {type: 'application/json'});
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = 'design-manifest.json';
  a.click();
  URL.revokeObjectURL(url);
}

// 7. Color picker sync
document.querySelectorAll('.gc-color-row input[type="color"]').forEach(function(picker) {
  picker.addEventListener('input', function() {
    var varName = this.getAttribute('data-var');
    var textInput = this.parentElement.querySelector('input[type="text"]');
    if (textInput) textInput.value = this.value;
    var swatch = this.closest('.gc-item').querySelector('.gc-swatch');
    if (swatch) swatch.style.background = this.value;
    updateRootVar('--' + varName, this.value);
  });
});
document.querySelectorAll('.gc-color-row input[type="text"]').forEach(function(input) {
  input.addEventListener('change', function() {
    var picker = this.parentElement.querySelector('input[type="color"]');
    var varName = picker.getAttribute('data-var');
    picker.value = this.value;
    var swatch = this.closest('.gc-item').querySelector('.gc-swatch');
    if (swatch) swatch.style.background = this.value;
    updateRootVar('--' + varName, this.value);
  });
});

// 8. Ctrl panel dragging (with null checks!)
var ctrlPanel = document.querySelector('.ctrl-panel');
var ctrlHeader = document.querySelector('.ctrl-header');
if (ctrlPanel && ctrlHeader) {
  var isDragging = false, startX, startY, initLeft, initTop;
  ctrlHeader.addEventListener('mousedown', function(e) {
    isDragging = true;
    startX = e.clientX;
    startY = e.clientY;
    var rect = ctrlPanel.getBoundingClientRect();
    initLeft = rect.left;
    initTop = rect.top;
  });
  document.addEventListener('mousemove', function(e) {
    if (!isDragging) return;
    ctrlPanel.style.left = (initLeft + e.clientX - startX) + 'px';
    ctrlPanel.style.top = (initTop + e.clientY - startY) + 'px';
    ctrlPanel.style.right = 'auto';
    ctrlPanel.style.bottom = 'auto';
  });
  document.addEventListener('mouseup', function() { isDragging = false; });
}
```

## EXECUTION PLAN:
1. Read the CURRENT file to extract the 20 sections' card content (preserve all the visual preview HTML)
2. Build the new file using Python string concatenation
3. Use proper indentation (not minified) for debugging
4. Write the output
5. Validate: count open vs close divs (must match), check all tab IDs, check ctrl-panel exists

CRITICAL: The script must extract the existing card preview content from the current file. Don't generate placeholder cards — use the REAL card content that already exists.

After running, validate with:
```python
open_divs = html.count('<div')
close_divs = html.count('</div')
assert open_divs == close_divs, f"Unbalanced divs: {open_divs} vs {close_divs}"
assert 'class="tab-content"' in html
assert 'class="ctrl-panel"' in html
assert 'class="ctrl-header"' in html
```

Run the script and report the validation results.

