#!/usr/bin/env python3
"""
Complete HTML rebuild for interactive-mockup.html
Extracts card content from existing file and rebuilds with proper structure.
"""

import re
import json
from pathlib import Path

# Read the current file to extract card sections
current_file = Path('/sessions/stoic-relaxed-carson/mnt/outputs/interactive-mockup.html')
current_html = current_file.read_text()

# Extract all dc-section blocks (sections 1-20)
section_pattern = r'<div class="dc-section"[^>]*id="s(\d+)"[^>]*>(.*?)</div>\s*<!--\s*end\s+dc-section\s*-->'
sections_match = re.findall(section_pattern, current_html, re.DOTALL)

print(f"Found {len(sections_match)} sections in current file")

# Build a dict of sections with their content
sections_content = {}
for match in sections_match:
    section_num = match[0]
    section_body = match[1]
    sections_content[section_num] = section_body
    print(f"  Section {section_num}: extracted")

# ============================================================================
# BUILD NEW HTML
# ============================================================================

html = """<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
