    document.querySelectorAll('.tab-btn').forEach(function(btn) {
      btn.addEventListener('click', function() {
        document.querySelectorAll('.tab-btn').forEach(function(b) {
          b.classList.remove('active');
        });
        document.querySelectorAll('.tab-content').forEach(function(c) {
          c.classList.remove('active');
        });
        btn.classList.add('active');
        var tabId = btn.getAttribute('data-tab');
        var tabContent = document.getElementById(tabId);
        if (tabContent) {
          tabContent.classList.add('active');
        }
      });
    });

    // ========================================
    // 2. CARD SELECTION
    // ========================================
    function selectCard(card) {
      var section = card.closest('.dc-section');
      if (section) {
        section.querySelectorAll('.dc-card').forEach(function(c) {
          c.classList.remove('selected');
        });
      }
      card.classList.add('selected');

      var varName = card.getAttribute('data-var');
      var varValue = card.getAttribute('data-val');
      if (varName && varValue && varName !== 'visual-only') {
        updateRootVar('--' + varName, varValue);
        var ctrl = document.getElementById('ctrl-' + varName);
        if (ctrl) {
          for (var i = 0; i < ctrl.options.length; i++) {
            if (ctrl.options[i].value === varValue) {
              ctrl.value = varValue;
              break;
            }
          }
        }
      }
    }

    // ========================================
    // 3. UPDATE CSS VARIABLE
    // ========================================
    function updateRootVar(name, value) {
      document.documentElement.style.setProperty(name, value);
    }

    // ========================================
    // 4. RESET THEME
    // ========================================
    function resetTheme() {
      var defaults = {
        '--heading-font': "'Playfair Display', serif",
        '--body-font': "'Inter', sans-serif",
        '--mono-font': "'DM Mono', monospace",
        '--accent-font': "'Inter', sans-serif",
        '--accent-gold': '#C9A96E',
        '--bg-body': '#0A0A0A',
        '--bg-card': '#141312',
        '--text-primary': '#F5F5F5',
        '--text-secondary': '#888888',
        '--color-green': '#2ECC71',
        '--color-red': '#E74C3C',
        '--color-orange': '#F39C12',
        '--border-radius': '6px',
        '--btn-radius': '6px',
        '--input-radius': '6px'
      };
      for (var k in defaults) {
        document.documentElement.style.setProperty(k, defaults[k]);
      }
      document.querySelectorAll('.dc-section').forEach(function(s) {
        s.querySelectorAll('.dc-card').forEach(function(c, i) {
          if (i === 0) {
            c.classList.add('selected');
          } else {
            c.classList.remove('selected');
          }
        });
      });
      document.querySelectorAll('.ctrl-group select').forEach(function(sel) {
        sel.selectedIndex = 0;
      });
    }

    // ========================================
    // 5. TOGGLE CONTROL PANEL
    // ========================================
    function toggleCtrlPanel() {
      var panel = document.querySelector('.ctrl-panel');
      if (panel) {
        panel.classList.toggle('collapsed');
      }
    }

    // ========================================
    // 6. SAVE THEME (EXPORT MANIFEST)
    // ========================================
    function saveTheme() {
      var manifest = {
        generatedAt: new Date().toISOString(),
        cssVariables: {},
        selections: {}
      };
      var style = document.documentElement.style;
      for (var i = 0; i < style.length; i++) {
        var prop = style[i];
        if (prop.startsWith('--')) {
          manifest.cssVariables[prop] = style.getPropertyValue(prop).trim();
        }
      }
      document.querySelectorAll('.dc-card.selected').forEach(function(card) {
        var section = card.closest('.dc-section');
        var title = section ? (section.querySelector('.dc-section-title') || {textContent: 'unknown'}).textContent : 'unknown';
        var label = (card.querySelector('.dc-label span:first-child') || {textContent: 'unknown'}).textContent;
        manifest.selections[title] = label;
      });
      var blob = new Blob([JSON.stringify(manifest, null, 2)], {type: 'application/json'});
      var url = URL.createObjectURL(blob);
      var a = document.createElement('a');
      a.href = url;
      a.download = 'design-manifest.json';
      a.click();
      URL.revokeObjectURL(url);
    }

    // ========================================
    // 7. CONTROL PANEL DRAGGING
    // ========================================
    var ctrlPanel = document.querySelector('.ctrl-panel');
    var ctrlHeader = document.querySelector('.ctrl-header');
    if (ctrlPanel && ctrlHeader) {
      var isDragging = false;
      var startX = 0;
      var startY = 0;
      var initLeft = 0;
      var initTop = 0;

      ctrlHeader.addEventListener('mousedown', function(e) {
        isDragging = true;
        startX = e.clientX;
        startY = e.clientY;
        var rect = ctrlPanel.getBoundingClientRect();
        initLeft = rect.left;
        initTop = rect.top;
      });

      document.addEventListener('mousemove', function(e) {
        if (!isDragging) return;
        ctrlPanel.style.left = (initLeft + e.clientX - startX) + 'px';
        ctrlPanel.style.top = (initTop + e.clientY - startY) + 'px';
        ctrlPanel.style.right = 'auto';
        ctrlPanel.style.bottom = 'auto';
      });

      document.addEventListener('mouseup', function() {
        isDragging = false;
      });
    }
  </script>

</body>
</html>
"""

